<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Http\Responses\ApiResponse; use App\Models\AcademicCalendarEvent; use Illuminate\Http\Request;
class AcademicCalendarEventController extends Controller { public function index(Request $r){$x=AcademicCalendarEvent::orderBy('start_date')->paginate($r->integer('per_page',50));return ApiResponse::success($x->items(),null,['total'=>$x->total()]);} public function store(Request $r){$d=$r->validate(['academic_year_id'=>['nullable','exists:academic_years,id'],'name'=>['required','string','max:255'],'event_type'=>['required','string','max:100'],'start_date'=>['required','date'],'end_date'=>['required','date','after_or_equal:start_date'],'affected_levels'=>['nullable','string','max:255'],'suspends_clinical_training'=>['boolean'],'notes'=>['nullable','string','max:3000']]);return ApiResponse::success(AcademicCalendarEvent::create($d),'Calendar event created.',[],201);} }
